package com.example.rokidkeyboardbridge;
public final class KneeRestTest {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public static void main(String[] args){EmbodiedScenePolicy p=new EmbodiedScenePolicy();p.user("寝たまま立膝にして",1000);ok(p.correctedRest()&&p.restMotion(2000)==5,"knee command");ok(RestAnimationTimeline.frame(5,10000)==16&&!RestAnimationTimeline.moving(5,10000),"holds knee without a loop");String[] faces={"キス顔にして","困った顔にして","せつない顔にして","こらえる顔にして"};for(int i=0;i<faces.length;i++){p.user(faces[i],12000+i*1000);ok(p.restMotion(12500+i*1000)==5&&p.restFace()==i+1,"face keeps knee");ok(RestAnimationTimeline.frame(p.restMotion(12500+i*1000),p.local(12500+i*1000))==16,"face does not restart knee bend");p.answer("切り替えます。",FullBodyPoseCatalog.Kind.NEUTRAL,12600+i*1000);}
 p.user("寝たまま立膝のまま身じろぎして",20000);ok(p.restMotion(21000)==7,"small fidget retains knee");ok(RestAnimationTimeline.frame(7,2000)==16,"same knee body during fidget");p.user("困った顔にして",22000);ok(p.restMotion(22100)==7&&p.restFace()==2,"fidget face combination");ok(p.local(22100)>2000,"expression keeps the motion clock");p.user("身じろぎを止めて",23000);ok(p.restMotion(23100)==5&&RestAnimationTimeline.frame(5,p.local(23100))==16,"stop keeps knee");p.user("寝たまま脚を伸ばして",24000);ok(p.restMotion(24100)==6,"lowering transition");ok(RestAnimationTimeline.frame(6,10000)==9,"lower settles to master");
 p.user("寝たまま立膝にして",30000);p.user("困った顔にして",40000);p.answer("切り替えます。",FullBodyPoseCatalog.Kind.NEUTRAL,40100);p.user("戻って",41000);p.user("戻って",41100);ok(p.restMotion(41200)==5&&RestAnimationTimeline.frame(5,p.local(41200))==16,"undo keeps held knee, duplicate safe");p.user("立って",42000);ok(!p.correctedRest(),"stand exits");
 for(String q:new String[]{"彼女が立膝にしてと言った","立膝の意味を教えて","寝たまま立膝にしないで","私は足を伸ばしている"})ok(RestAnimationIntent.action(q)<0,"not local control");
 for(int m=5;m<=7;m++)for(int age=0;age<10000;age+=100){int frame=RestAnimationTimeline.frame(m,age);ok(frame==9||frame>=14&&frame<=17,"bounded knee frame");float mix=RestAnimationTimeline.mix(m,age);ok(mix>=0&&mix<=1,"bounded blend");}
 System.out.println("PASS "+n+" knee/cloth-keyframe/face/hold/fidget/stop/return checks");}
}
